import{c as t,Q as a,j as o,m as r}from"./chunks/framework.g_l1frA7.js";const u=JSON.parse('{"title":"Scenarios","description":"","frontmatter":{},"headers":[],"relativePath":"guide/scenarios.md","filePath":"guide/scenarios.md","lastUpdated":null}'),n={name:"guide/scenarios.md"};function s(i,e,d,c,h,l){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="scenarios" tabindex="-1">Scenarios <a class="header-anchor" href="#scenarios" aria-label="Permalink to &quot;Scenarios&quot;">​</a></h1><p>“What if I …?” forecasting with deterministic finance tools — natural-language entry, math exit.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ol><li>Type a question on <strong>Scenarios</strong> (e.g. “What if I raise rent to $2,400 and add $300/month to my emergency fund for a year?”).</li><li>The Copilot maps_free text to structured tool calls (adjust expenses, set contributions, change horizon).</li><li><code>finsight-core::forecast</code> runs the math — balances forward from current ledger plus recurring assumptions — and returns a dated ledger projection.</li><li>The Copilot narrates the outcome with figures. The scenario is not saved unless you save it.</li></ol><h2 id="which-numbers-change" tabindex="-1">Which numbers change <a class="header-anchor" href="#which-numbers-change" aria-label="Permalink to &quot;Which numbers change&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Effect</th></tr></thead><tbody><tr><td><code>set_monthly_contribution</code></td><td>Alters goal funding and end balance</td></tr><tr><td><code>adjust_recurring</code></td><td>Shifts cash-flow calendar and safe-to-spend</td></tr><tr><td><code>set_expense</code> / <code>set_income</code></td><td>Reprojects income/expenses and savings rate</td></tr><tr><td><code>set_carryover</code></td><td>Changes next-month opening envelope</td></tr></tbody></table><p>All tools are allow-listed in <code>planner.rs::ACTION_KINDS</code> and the system prompt forbids inventing totals.</p><h2 id="saving-comparing" tabindex="-1">Saving &amp; comparing <a class="header-anchor" href="#saving-comparing" aria-label="Permalink to &quot;Saving &amp; comparing&quot;">​</a></h2><p>Save a scenario to revisit it after new transactions import — the projection refreshes against the latest ledger. Compare two saved scenarios side-by-side to see which trade-off is cheaper in 12 months.</p><p>See also: <a href="/FinSight/guide/cashflow">Cash Flow</a>, <a href="/FinSight/copilot/scenarios">Copilot → Scenarios</a>.</p>',10)])])}const m=t(n,[["render",s]]);export{u as __pageData,m as default};
